var speed = new ArcElasticSlider
{
    Label = "Playback speed",
    Width = 300,
    Min = 0.5,
    Max = 2,
    Step = 0.25,
    Value = 1.25,
    StartIcon = "minus",
    EndIcon = "plus",
    Marks = new List<ArcSliderMark>
    {
        new(1, "1x"),
        new(1.5, "1.5x"),
        new(2, "2x")
    },
    Format = value => value.ToString("0.##") + "x"
};

speed.ValueCommitted += (_, _) => Save(speed.Value);
